'use server';

import { revalidateTag } from 'next/cache';

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string;
  const content = formData.get('content') as string;

  if (!title || !content) {
    return { success: false, error: 'Title and content are required' };
  }

  try {
    // Simulate creating a post (replace with your actual data storage logic)
    // For example: await db.posts.create({ title, content })
    console.log('Creating post:', { title, content });

    // Invalidate the "posts" cache tag to ensure fresh data is fetched
    // revalidateTag ensures that the next request will wait for fresh data
    // and will NOT serve stale cached content
    revalidateTag('posts');

    return { success: true };
  } catch (error) {
    console.error('Failed to create post:', error);
    return { success: false, error: 'Failed to create post' };
  }
}

